operation.add:
if (!empty($data['gls'])) {
	$this->ensureGlsColumn();
}

if (!empty($data['gls'])) {
	$this->db->query("UPDATE `" . DB_PREFIX . "order` SET gls = '" . $this->db->escape($data['gls']) . "' WHERE order_id = '" . (int)$order_id . "'");
}

private function ensureGlsColumn() {
	$query = $this->db->query("SHOW COLUMNS FROM `" . DB_PREFIX . "order` LIKE 'gls'");

	if (!$query->num_rows) {
		$this->db->query("ALTER TABLE `" . DB_PREFIX . "order` ADD `gls` TEXT NULL AFTER `shipping_code`");
	}
}

if (isset($order_info['shipping_code']) && $order_info['shipping_code'] == 'gls.gls' && !empty($order_info['gls'])) {
	$data['shipping_method'] .= '<br /><strong>GLS ParcelShop / Paketomat</strong><br /><strong>GLS:</strong> ' . htmlspecialchars($order_info['gls'], ENT_QUOTES, 'UTF-8');
}

$data['gls'] = isset($order_info['gls']) ? $order_info['gls'] : '';
$data['gls_create'] = '';
$data['gls_shipment'] = array();
$data['button_gls_create_shipment'] = 'Pošalji naljepnicu u GLS';

if (isset($order_info['shipping_code']) && $order_info['shipping_code'] == 'gls.gls') {
	$this->load->model('extension/shipping/gls');

	$this->model_extension_shipping_gls->installSchema();

	$data['gls_shipment'] = $this->model_extension_shipping_gls->getShipmentByOrderId($this->request->get['order_id']);
	$data['gls_create'] = $this->url->link('extension/shipping/gls/createShipment', 'token=' . $this->session->data['token'] . '&order_id=' . (int)$this->request->get['order_id'], true);
}

if ($data['gls']) {
	$data['shipping_method'] .= '<br /><small><strong>GLS:</strong> ' . htmlspecialchars($data['gls'], ENT_QUOTES, 'UTF-8') . '</small>';
}

if ($data['gls_create']) {
	$data['shipping_method'] .= '<div style="margin-top:8px;">';

	$gls_display_id = !empty($data['gls_shipment']['parcel_number']) ? $data['gls_shipment']['parcel_number'] : (!empty($data['gls_shipment']['parcel_id']) ? $data['gls_shipment']['parcel_id'] : '');

	if ($gls_display_id) {
		$data['shipping_method'] .= '<span class="label label-success">Poslano u GLS: ' . htmlspecialchars($gls_display_id, ENT_QUOTES, 'UTF-8') . '</span>';
	} else {
		$data['shipping_method'] .= '<button type="button" id="button-gls-create" data-loading-text="' . htmlspecialchars($this->language->get('text_loading'), ENT_QUOTES, 'UTF-8') . '" class="btn btn-success btn-xs"><i class="fa fa-truck"></i> ' . $data['button_gls_create_shipment'] . '</button>';
	}

	$data['shipping_method'] .= '</div>';
}

if (isset($this->session->data['shipping_method']['code']) && $this->session->data['shipping_method']['code'] == 'gls.gls') {
	if (empty($this->session->data['gls']) || stripos($this->session->data['gls'], 'undefined') !== false) {
		$redirect = $this->url->link('checkout/checkout', '', true);
	}

	$gls_product_ids = array();

	foreach ($this->cart->getProducts() as $gls_product) {
		if (!empty($gls_product['shipping'])) {
			$gls_product_ids[(int)$gls_product['product_id']] = (int)$gls_product['product_id'];
		}
	}

	if ($gls_product_ids) {
		$gls_allowed_query = $this->db->query("SELECT COUNT(*) AS total FROM " . DB_PREFIX . "product WHERE product_id IN (" . implode(',', $gls_product_ids) . ") AND TRIM(upc) = '1'");

		if ((int)$gls_allowed_query->row['total'] !== count($gls_product_ids)) {
			unset($this->session->data['shipping_method']);
			unset($this->session->data['gls']);
			$redirect = $this->url->link('checkout/checkout', '', true);
		}
	}
} else {
	unset($this->session->data['gls']);
}

$order_data['gls'] = '';

if (isset($this->session->data['shipping_method']['code']) && $this->session->data['shipping_method']['code'] == 'gls.gls' && !empty($this->session->data['gls'])) {
	$order_data['gls'] = $this->session->data['gls'];
}

public function saveGlsPoint() {
	$json = array();

	if (isset($this->request->post['gls'])) {
		$this->session->data['gls'] = strip_tags($this->request->post['gls']);
		$json['success'] = true;
	} else {
		$json['error'] = true;
	}

	$this->response->addHeader('Content-Type: application/json');
	$this->response->setOutput(json_encode($json));
}

$data['gls_available'] = false;

foreach ($data['shipping_methods'] as $shipping_method) {
	if (!empty($shipping_method['quote'])) {
		foreach ($shipping_method['quote'] as $quote) {
			if (isset($quote['code']) && $quote['code'] == 'gls.gls') {
				$data['gls_available'] = true;
				break 2;
			}
		}
	}
}

if (!isset($this->session->data['shipping_method']['code'])) {
	unset($this->session->data['gls']);
}

if ($data['code'] != 'gls.gls') {
	unset($this->session->data['gls']);
}

if ($data['code'] == 'gls.gls' && isset($this->session->data['gls'])) {
	$data['gls'] = $this->session->data['gls'];
} else {
	$data['gls'] = '';
}

$data['gls_filter_type'] = $this->config->get('gls_filter_type');
$data['error_gls'] = $this->language->get('error_gls');

if (isset($this->request->post['shipping_method']) && $this->request->post['shipping_method'] == 'gls.gls') {
	$gls = '';

	if (isset($this->request->post['gls'])) {
		$gls = trim(strip_tags($this->request->post['gls']));
	} elseif (isset($this->session->data['gls'])) {
		$gls = trim($this->session->data['gls']);
	}

	if ($gls == '' || stripos($gls, 'undefined') !== false) {
		$json['error']['warning'] = $this->language->get('error_gls');
	}
}

if ($this->request->post['shipping_method'] == 'gls.gls') {
	$this->session->data['gls'] = isset($this->request->post['gls']) ? strip_tags($this->request->post['gls']) : (isset($this->session->data['gls']) ? $this->session->data['gls'] : '');
} else {
	unset($this->session->data['gls']);
}

if (isset($this->session->data['shipping_method']['code']) && $this->session->data['shipping_method']['code'] == 'gls.gls') {
	if (empty($this->session->data['gls']) || stripos($this->session->data['gls'], 'undefined') !== false) {
		$redirect = $this->url->link('checkout/checkout', '', true);
	}

	$gls_product_ids = array();

	foreach ($this->cart->getProducts() as $gls_product) {
		if (!empty($gls_product['shipping'])) {
			$gls_product_ids[(int)$gls_product['product_id']] = (int)$gls_product['product_id'];
		}
	}

	if ($gls_product_ids) {
		$gls_allowed_query = $this->db->query("SELECT COUNT(*) AS total FROM " . DB_PREFIX . "product WHERE product_id IN (" . implode(',', $gls_product_ids) . ") AND TRIM(upc) = '1'");

		if ((int)$gls_allowed_query->row['total'] !== count($gls_product_ids)) {
			unset($this->session->data['shipping_method']);
			unset($this->session->data['gls']);
			$redirect = $this->url->link('checkout/checkout', '', true);
		}
	}
} else {
	unset($this->session->data['gls']);
}

$order_data['gls'] = '';

if (isset($this->session->data['shipping_method']['code']) && $this->session->data['shipping_method']['code'] == 'gls.gls' && !empty($this->session->data['gls'])) {
	$order_data['gls'] = $this->session->data['gls'];
}

